        <SidebarGroupLabel>工作区</SidebarGroupLabel>
        <SidebarGroupAction aria-label="添加 workspace" onClick={onAdd}>
          <Plus />
        </SidebarGroupAction>
        <SidebarGroupContent>
          <SidebarMenu>
            {workspaces.map((record) => (
              <WorkspaceItem
                currentRoot={currentRoot}
                key={record.root}
                onOpen={onOpen}
                onRemove={onRemove}
                record={record}
              />
            ))}
          </SidebarMenu>
        </SidebarGroupContent>
      </SidebarGroup>
    </Sidebar>
  );
}

